theorems.type:
∀ {c : Context} {signature : Vote → Prop}
    {h round block : Nat} {votes : List Vote} (ok : CommitValid c signature h round block votes), 2*Committee.totalPower c.unit (activeAt c h).members <
      3*signedPower c (activeAt c h).members (votes.map Vote.key)

∀ {c : Etna.Design.Consensus.Context}
  {signature : Etna.Design.Consensus.Vote → Prop} {h : Nat} {e : Etna.Design.Locking.Execution} {r b : Nat}
  {votes : List Etna.Design.Consensus.Vote},
  Etna.Design.Locking.CommitAttribution e r b votes →
    Etna.Design.Consensus.CommitValid c signature h r b votes →
      Etna.Design.Locking.Commit c.unit (Etna.Design.Consensus.activeAt c h).members e r b

∀ {s t : Etna.Design.Current.Registry.State} {id : Nat}
  {f : Etna.Design.Current.Registry.Bond → Option Etna.Design.Current.Registry.Bond},
  Etna.Design.Current.Registry.modify s id f = Option.some t → t.nextId = s.nextId ∧ t.keyId = s.keyId

∀ {r : Etna.Design.Current.Blocks.GenerationPolicy} {p : Etna.Design.Current.Blocks.Header}
  {bs : List Etna.Design.Current.Blocks.Block},
  Etna.Design.Current.Blocks.Chain r p bs → Etna.Design.cursorSteps (Etna.Design.Current.Blocks.cuts p bs) = Bool.true

∀ {r : Etna.Design.Current.Blocks.GenerationPolicy} {p : Etna.Design.Current.Blocks.Header}
  {bs : List Etna.Design.Current.Blocks.Block},
  Etna.Design.Current.Blocks.Chain r p bs → (Etna.Design.Current.Blocks.terminal p bs).height = p.height + bs.length

∀ {r : Etna.Design.Current.Blocks.GenerationPolicy} {p : Etna.Design.Current.Blocks.Header}
  {b : Etna.Design.Current.Blocks.Block},
  p.height = r.consensus.originHeight → Etna.Design.Current.Blocks.AnchorValid r p b → b.body.anchorWitness = Bool.true

∀ {r : Etna.Design.Current.Blocks.GenerationPolicy} {p : Etna.Design.Current.Blocks.Header}
  {b : Etna.Design.Current.Blocks.Block},
  r.catalogue (Etna.Design.Current.Blocks.selectedRules b) = Option.none → ¬Etna.Design.Current.Blocks.Valid r p b

∀ {r : Etna.Design.Current.Blocks.GenerationPolicy} {p : Etna.Design.Current.Blocks.Header}
  {b : Etna.Design.Current.Blocks.Block},
  Etna.Design.Current.Blocks.Valid r p b → p.cursor ≤ b.header.cursor ∧ b.header.cursor ≤ p.cursor + 1

∀ {env : Etna.Design.Current.Protocol.Environment} {w : Etna.Design.Current.Protocol.World}
  {a : Etna.Design.Current.Protocol.Landing} (segment : Etna.Design.Current.Protocol.Suffix env w a),
  Etna.Design.Current.Protocol.HashBound env (Etna.Design.Current.Blocks.terminal segment.parent segment.blocks)

∀ {env : Etna.Design.Current.Protocol.Environment} {w t : Etna.Design.Current.Protocol.World}
  {call : Etna.Design.Current.Protocol.Call},
  Etna.Design.Current.Protocol.execute env w call = Option.some t → Etna.Design.Current.Journal.Effect env w t

∀ {env : Etna.Design.Current.Protocol.Environment} {w t : Etna.Design.Current.Protocol.World}
  {call : Etna.Design.Current.Protocol.Call},
  Etna.Design.Current.Protocol.execute env w call = Option.some t → Etna.Design.Current.Journal.RecordEffect w t

∀ {s t : Etna.Design.Current.RegistryMachine.State} {id : Nat}
  {f : Etna.Design.Staking.Bond → Option Etna.Design.Staking.Bond},
  Etna.Design.Current.RegistryMachine.editValue s id f = Option.some t → Etna.Design.Current.RegistryMachine.Stable s t

∀ {env : Etna.Design.Current.RegistryPayments.PaymentEnvironment} {s : Etna.Design.Current.RegistryPayments.State}
  {v : Etna.Design.Current.RegistryMachine.InboxView} {now caller : Nat}
  {action : Etna.Design.Current.RegistryMachine.Action},
  Etna.Design.Current.RegistryPayments.executeTransaction env s v now caller action = Option.none →
    Etna.Design.Current.RegistryPayments.transact env s v now caller action = s

∀ {env : Etna.Design.Current.RegistryPayments.PaymentEnvironment} {s t : Etna.Design.Current.RegistryPayments.State}
  {v : Etna.Design.Current.RegistryMachine.InboxView} {now caller : Nat}
  {action : Etna.Design.Current.RegistryMachine.Action} {receipts : List Etna.Design.Current.RegistryPayments.Payment},
  Etna.Design.Current.RegistryPayments.executeTransaction env s v now caller action = Option.some (t, receipts) →
    Etna.Design.Current.RegistryMachine.execute s.registry v now action = Option.some t.registry

∀ {env : Etna.Design.Current.Protocol.Environment} {initial : Etna.Design.Current.Protocol.World}
  {start : Option Etna.Design.Current.Protocol.StartData}
  {H : Etna.Design.Checkpoint → Etna.Design.Current.Protocol.Header} {records : List Etna.Design.Checkpoint},
  Etna.Design.Current.Protocol.Custody.Linked env initial start H records →
    ∀ (head : Etna.Design.Checkpoint) (rest : List Etna.Design.Checkpoint),
      records = head :: rest → ∀ (cp : Etna.Design.Checkpoint), cp ∈ records → cp.height ≤ head.height

∀ {env : Etna.Design.Current.Protocol.Environment} {initial : Etna.Design.Current.Protocol.World}
  {start : Option Etna.Design.Current.Protocol.StartData}
  {H : Etna.Design.Checkpoint → Etna.Design.Current.Protocol.Header} {records : List Etna.Design.Checkpoint}
  {trusted : Etna.Design.Checkpoint},
  Etna.Design.Current.Protocol.Custody.Linked env initial start H records →
    trusted ∈ records →
      Etna.Design.Current.Protocol.Custody.Linked env initial start H
          (List.filter (fun cp => Decidable.decide (cp.height ≤ trusted.height)) records) ∧
        (List.filter (fun cp => Decidable.decide (cp.height ≤ trusted.height)) records).head? = Option.some trusted

∀ {env : Etna.Design.Current.Protocol.Environment} {initial : Etna.Design.Current.Protocol.World}
  {start : Option Etna.Design.Current.Protocol.StartData}
  {H G : Etna.Design.Checkpoint → Etna.Design.Current.Protocol.Header} {records : List Etna.Design.Checkpoint},
  Etna.Design.Current.Protocol.Custody.Linked env initial start H records →
    (∀ (cp : Etna.Design.Checkpoint), cp ∈ records → G cp = H cp) →
      Etna.Design.Current.Protocol.Custody.Linked env initial start G records

∀ {env : Etna.Design.Current.Protocol.Environment} {initial : Etna.Design.Current.Protocol.World}
  {start : Option Etna.Design.Current.Protocol.StartData}
  {H : Etna.Design.Checkpoint → Etna.Design.Current.Protocol.Header} {records : List Etna.Design.Checkpoint},
  Etna.Design.Current.Protocol.Custody.Linked env initial start H records → ∃ s, start = Option.some s

∀ (w : Etna.Design.Current.Protocol.World) (height hash root block timestamp generation : Nat),
  have t := Etna.Design.Current.Protocol.writeStart w height hash root block timestamp generation;
  (t.inbox.checkpoint, w.inbox.snapshot) ∈ t.activeSnapshots

∀ {env : Etna.Design.Current.Protocol.Environment} {w : Etna.Design.Current.Protocol.World} {image : Etna.Design.Hash}
  {d : Etna.Design.StatementData},
  Etna.Design.Current.Protocol.ImageCertifies env w image d → Etna.Design.Current.Protocol.Certifies env w d

∀ {hash : Etna.Design.Current.Archive.Header → Etna.Design.Hash} {parentOf : Etna.Design.Hash → Etna.Design.Hash}
  {cfg : Etna.Design.Current.Finality.Config} {origin : Etna.Design.Cut} {reference : Nat}
  {archive : List Etna.Design.Current.Archive.Header} {p : Etna.Design.Current.Archive.Header}
  {bs : List Etna.Design.Current.Archive.Block},
  Etna.Design.Current.Archive.Authenticated hash parentOf cfg origin reference archive p bs →
    ∀ (b : Etna.Design.Current.Archive.Block), b ∈ bs → Etna.Design.Current.Blocks.Block.header b ∈ archive

∀ {hash : Etna.Design.Current.Archive.Header → Etna.Design.Hash} {parentOf : Etna.Design.Hash → Etna.Design.Hash}
  {cfg : Etna.Design.Current.Finality.Config} {origin : Etna.Design.Cut} {reference : Nat}
  {archive : List Etna.Design.Current.Archive.Header} {p : Etna.Design.Current.Archive.Header}
  {bs : List Etna.Design.Current.Archive.Block},
  Etna.Design.Current.Archive.Authenticated hash parentOf cfg origin reference archive p bs →
    ∀ (b : Etna.Design.Current.Archive.Block),
      b ∈ bs → parentOf (Etna.Design.Current.Blocks.Block.header b).elHash = b.body.parentHash

∀ {hash : Etna.Design.Current.Archive.Header → Etna.Design.Hash} {parentOf : Etna.Design.Hash → Etna.Design.Hash}
  {cfg : Etna.Design.Current.Finality.Config} {origin : Etna.Design.Cut} {reference : Nat}
  {archive : List Etna.Design.Current.Archive.Header} {p : Etna.Design.Current.Archive.Header}
  {bs : List Etna.Design.Current.Archive.Block} {registry : Etna.Design.Current.RegistryMachine.State},
  Etna.Design.Current.Archive.Authenticated hash parentOf cfg origin reference archive p bs →
    cfg.genesisCutoff ≤ cfg.originBlock →
      ∀ (height : Nat),
        (Etna.Design.Consensus.activeAt (Etna.Design.Current.Finality.derive cfg registry archive) height).cutoff ≤
          reference

∀ {hash : Etna.Design.Current.Archive.Header → Etna.Design.Hash} {parentOf : Etna.Design.Hash → Etna.Design.Hash}
  {cfg : Etna.Design.Current.Finality.Config} {origin : Etna.Design.Cut} {reference : Nat}
  {archive : List Etna.Design.Current.Archive.Header} {p : Etna.Design.Current.Archive.Header}
  {bs : List Etna.Design.Current.Archive.Block} {registry : Etna.Design.Current.RegistryMachine.State},
  Etna.Design.Current.Archive.Authenticated hash parentOf cfg origin reference archive p bs →
    Etna.Design.Current.Finality.Ready cfg registry archive (Etna.Design.Current.Blocks.terminal p bs).height →
      (Etna.Design.Consensus.activeAt (Etna.Design.Current.Finality.derive cfg registry archive)
            (Etna.Design.Current.Blocks.terminal p bs).height).cutoff ≤
        reference

∀ {hash : Etna.Design.Current.Archive.Header → Etna.Design.Hash} {parentOf : Etna.Design.Hash → Etna.Design.Hash}
  {cfg : Etna.Design.Current.Finality.Config} {origin : Etna.Design.Cut} {reference : Nat}
  {archive : List Etna.Design.Current.Archive.Header} {p : Etna.Design.Current.Archive.Header}
  {bs : List Etna.Design.Current.Archive.Block},
  Etna.Design.Current.Archive.Authenticated hash parentOf cfg origin reference archive p bs →
    ∀ (h : Etna.Design.Current.Archive.Header), h ∈ archive → hash h = h.elHash

∀ {hash : Etna.Design.Current.Archive.Header → Etna.Design.Hash} {parentOf : Etna.Design.Hash → Etna.Design.Hash}
  {cfg : Etna.Design.Current.Finality.Config} {origin : Etna.Design.Cut} {reference : Nat}
  {archive : List Etna.Design.Current.Archive.Header} {p : Etna.Design.Current.Archive.Header}
  {bs : List Etna.Design.Current.Archive.Block},
  Etna.Design.Current.Archive.Authenticated hash parentOf cfg origin reference archive p bs →
    ∀ (b : Etna.Design.Current.Archive.Block),
      b ∈ bs → hash (Etna.Design.Current.Blocks.Block.header b) = (Etna.Design.Current.Blocks.Block.header b).elHash

∀ {hash : Etna.Design.Current.Archive.Header → Etna.Design.Hash} {parentOf : Etna.Design.Hash → Etna.Design.Hash}
  {cfg : Etna.Design.Current.Finality.Config} {origin : Etna.Design.Cut} {reference : Nat}
  {archive : List Etna.Design.Current.Archive.Header} {p : Etna.Design.Current.Archive.Header}
  {bs : List Etna.Design.Current.Archive.Block},
  Etna.Design.Current.Archive.Authenticated hash parentOf cfg origin reference archive p bs →
    ∀ (h : Etna.Design.Current.Archive.Header), h ∈ archive → h.anchor.number ≤ reference

∀ {hash : Etna.Design.Current.Archive.Header → Etna.Design.Hash} {parentOf : Etna.Design.Hash → Etna.Design.Hash}
  {cfg : Etna.Design.Current.Finality.Config} {origin : Etna.Design.Cut} {reference : Nat}
  {archive : List Etna.Design.Current.Archive.Header} {p : Etna.Design.Current.Archive.Header}
  {bs : List Etna.Design.Current.Archive.Block},
  Etna.Design.Current.Archive.Authenticated hash parentOf cfg origin reference archive p bs →
    Etna.Design.Current.Archive.Linked parentOf p (List.map Etna.Design.Current.Blocks.Block.header bs)

∀ {hash : Etna.Design.Current.Archive.Header → Etna.Design.Hash} {parentOf : Etna.Design.Hash → Etna.Design.Hash}
  {cfg : Etna.Design.Current.Finality.Config} {origin : Etna.Design.Cut} {reference : Nat}
  {archive : List Etna.Design.Current.Archive.Header} {p : Etna.Design.Current.Archive.Header}
  {bs : List Etna.Design.Current.Archive.Block},
  Etna.Design.Current.Archive.Authenticated hash parentOf cfg origin reference archive p bs →
    ∃ root,
      root.height = cfg.originHeight ∧ Etna.Design.BlockValidity.Header.cut root = origin ∧ hash root = root.elHash

∀ {env : Etna.Design.Current.Protocol.Environment} {w : Etna.Design.Current.Protocol.World}
  {d : Etna.Design.StatementData} {archive : List Etna.Design.Current.Protocol.Header}
  {p : Etna.Design.Current.Protocol.Header} {bs : List Etna.Design.Current.Protocol.Block},
  Etna.Design.Current.Protocol.BatchCertificate env w d archive p bs →
    Etna.Design.Current.Protocol.CertificateFootprint env w d.input.l1ReferenceBlockNumber →
      Etna.Design.Current.Protocol.LiveBatchCertificate env w d archive p bs

∀ {env : Etna.Design.Current.Protocol.Environment} {w : Etna.Design.Current.Protocol.World}
  {d : Etna.Design.StatementData},
  Etna.Design.Current.Protocol.Certifies env w d → d.input.activeCommitteeSnapshot ≤ d.input.l1ReferenceBlockNumber

∀ {env : Etna.Design.Current.Protocol.Environment} {w : Etna.Design.Current.Protocol.World}
  {d : Etna.Design.StatementData},
  Etna.Design.Current.Protocol.LiveCertifies env w d → d.input.activeCommitteeSnapshot ≤ d.input.l1ReferenceBlockNumber

∀ {env : Etna.Design.Current.Protocol.Environment} {initial : Etna.Design.Current.Protocol.World}
  {start : Etna.Design.Current.Protocol.StartData} {H : Etna.Design.Checkpoint → Etna.Design.Current.Protocol.Header}
  {records : List Etna.Design.Checkpoint},
  Etna.Design.Current.Protocol.Custody.Linked env initial (Option.some start) H records →
    (∀ (cp : Etna.Design.Checkpoint), cp ∈ records → Etna.Design.Current.Protocol.Custody.HeaderOf cp (H cp)) →
      ∀ (cp : Etna.Design.Checkpoint), cp ∈ records → start.height ≤ cp.height

∀ {env : Etna.Design.Current.Protocol.Environment} {first last : Etna.Design.Current.Protocol.World}
  (history : Etna.Design.Current.Protocol.Governance.DeployedTrace env first last),
  Etna.Design.Current.Protocol.Governance.AuthorizedUpgrades history → Etna.Design.Current.Protocol.Trace env first last

∀ {env : Etna.Design.Current.Protocol.Environment} {w t : Etna.Design.Current.Protocol.World}
  {request : Etna.Design.Current.Protocol.RecoveryRequest},
  Etna.Design.Current.Protocol.recover env w request = Option.some t → t.inbox.head = w.inbox.head

∀ {env : Etna.Design.Current.Protocol.Environment} {w : Etna.Design.Current.Protocol.World} {h : Nat}
  (candidate : Etna.Design.Current.CheckpointRisk.Candidate env w h),
  Etna.Design.Current.Finality.cutoff (Etna.Design.Current.Protocol.config w) candidate.headers h < w.number
